<?php
// Read input
$stdin = fopen('php://stdin', 'r');
$first_line = fgets($stdin);
list($n, $m) = explode(' ', trim($first_line));
$A = array();
for ($i = 1; $i <= $n; $i++) {
    $line = fgets($stdin);
    $row = array_map('intval', explode(' ', trim($line)));
    // make 1-indexed
    $A[$i] = array();
    for ($j = 1; $j <= $m; $j++) {
        $A[$i][$j] = $row[$j-1];
    }
}

// Constants
$S = 0;
$T = 6789;
$NV = 6790;

// Graph arrays
$head = array_fill(0, $NV, 0);
$to = array();
$cap = array();
$cost = array();
$next = array();
$ne = 1; // edge index starts at 1

function addEdge($from, $to_node, $capacity, $cost_val) {
    global $head, $to, $cap, $cost, $next, $ne;
    $ne++;
    $to[$ne] = $to_node;
    $cap[$ne] = $capacity;
    $cost[$ne] = $cost_val;
    $next[$ne] = $head[$from];
    $head[$from] = $ne;
    $ne++;
    $to[$ne] = $from;
    $cap[$ne] = 0;
    $cost[$ne] = -$cost_val;
    $next[$ne] = $head[$to_node];
    $head[$to_node] = $ne;
}

function group($i, $j) {
    return ($i + $j) & 1;
}

function id($i, $j) {
    global $m;
    return ($i - 1) * $m + $j;
}

// Build graph
for ($i = 1; $i <= $n; $i++) {
    for ($j = 1; $j <= $m; $j++) {
        if (group($i, $j) == 0) {
            addEdge($S, id($i, $j), 1, 0);
        } else {
            addEdge(id($i, $j), $T, 1, 0);
        }
    }
}

for ($i = 1; $i <= $n; $i++) {
    for ($j = 1; $j <= $m; $j++) {
        if (group($i, $j) == 0) {
            if ($i - 1 >= 1) {
                $c = ($A[$i][$j] != $A[$i-1][$j]) ? 1 : 0;
                addEdge(id($i, $j), id($i-1, $j), 1, $c);
            }
            if ($i + 1 <= $n) {
                $c = ($A[$i][$j] != $A[$i+1][$j]) ? 1 : 0;
                addEdge(id($i, $j), id($i+1, $j), 1, $c);
            }
            if ($j - 1 >= 1) {
                $c = ($A[$i][$j] != $A[$i][$j-1]) ? 1 : 0;
                addEdge(id($i, $j), id($i, $j-1), 1, $c);
            }
            if ($j + 1 <= $m) {
                $c = ($A[$i][$j] != $A[$i][$j+1]) ? 1 : 0;
                addEdge(id($i, $j), id($i, $j+1), 1, $c);
            }
        }
    }
}

// MCMF
function mcmf($S, $T) {
    global $NV, $head, $to, $cap, $cost, $next;
    $flow = 0;
    $cost_total = 0;
    $INF = 1000000000; // 1e9
    $d = array();
    $p = array();
    $inqueue = array();
    while (true) {
        // initialize d
        for ($i = 0; $i < $NV; $i++) {
            $d[$i] = $INF;
        }
        $queue = array();
        $queue[] = $S;
        $d[$S] = 0;
        $inqueue = array_fill(0, $NV, false);
        $inqueue[$S] = true;
        $head_idx = 0; // use array as queue with head index for efficiency
        while ($head_idx < count($queue)) {
            $v = $queue[$head_idx++];
            $inqueue[$v] = false;
            for ($x = $head[$v]; $x != 0; $x = $next[$x]) {
                $u = $to[$x];
                $cap_x = $cap[$x];
                $cost_x = $cost[$x];
                if ($cap_x > 0 && $d[$v] + $cost_x < $d[$u]) {
                    $d[$u] = $d[$v] + $cost_x;
                    $p[$u] = $x;
                    if (!$inqueue[$u]) {
                        $queue[] = $u;
                        $inqueue[$u] = true;
                    }
                }
            }
        }
        if ($d[$T] == $INF) break;
        $df = $INF;
        for ($i = $T; $i != $S; $i = $to[$p[$i] ^ 1]) {
            $df = min($df, $cap[$p[$i]]);
        }
        for ($i = $T; $i != $S; $i = $to[$p[$i] ^ 1]) {
            $cap[$p[$i]] -= $df;
            $cap[$p[$i] ^ 1] += $df;
        }
        $flow += $df;
        $cost_total += $df * $d[$T];
    }
    return array($flow, $cost_total);
}

list($f, $c) = mcmf($S, $T);
echo $c . "\n";
?>

